/// 高层 Message 编码 API
/// @param schema - 字段定义: [[fieldNum, wireType, fieldName], ...]
///   例如: [[1, "uint32", "id"], [2, "string", "name"]]
/// @param data - JavaScript 对象: { id: 123, name: "John" }
