#[napi]
pub fn encode_message(env: Env, schema: Array, data: Object) -> Result<Buffer> {
    let mut writer = WriterImpl::new();
    let schema_len = schema.len();

    for i in 0..schema_len {
        let field_def: Array = schema.get(i)?.unwrap();
        let field_num: u32 = field_def.get(0)?.unwrap();
        let field_type: String = field_def.get(1)?.unwrap();
        let field_name: String = field_def.get(2)?.unwrap();

        // 从 data 对象中获取字段值
        let value: JsUnknown = data.get(&field_name)?;
        if value.is_null()? || value.is_undefined()? {
            continue; // 跳过未设置的字段
