        // 写入字段标签 (field_num << 3 | wire_type)
        let wire_type = get_wire_type(&field_type);
        writer.write_varint32((field_num << 3) | wire_type);

        // 根据类型编码值
        match field_type.as_str() {
            "uint32" => {
                let val: u32 = value.coerce_to_number()?.get_uint32()?;
                writer.write_varint32(val);
            }
            "string" => {
                let val: String = value.coerce_to_string()?.into_utf8()?.as_str()?.to_owned();
