                writer.write_varint32(bytes.len() as u32);
                writer.write_bytes(bytes);
            }
            "int32" => {
                let val: i32 = value.coerce_to_number()?.get_int32()?;
                if val < 0 {
                    writer.write_varint64(val as i64 as u64);
                } else {
                    writer.write_varint32(val as u32);
